"import json\nimport os\n\npath = r\"C:\\Users\\a-6600\\.gemini\\antigravity\\brain\\defefd3d-03a6-48cc-ab0b-1fbc66f83de5\\.system_generated\\logs\\transcript.jsonl\"\nif not os.path.exists(path):\n    print(\"Transcript not found at\", path)\n    exit(1)\n\nfound = False\nwith open(path, \"r\", encoding=\"utf-8\") as f:\n    for idx, line in enumerate(f):\n        if \"fin_customers\" in line and \"CREATE TABLE\" in line:\n            obj = json.loads(line)\n            # Check tool calls\n            for tc in obj.get(\"tool_calls\", []):\n                args = tc.get(\"args\", {})\n                code = args.get(\"CodeContent\") or args.get(\"ReplacementContent\")\n                if code and \"CREATE TABLE public.fin_customers\" in code:\n                    print(f\"Found SQL table definition in tool call at line {idx}\")\n                    with open(\"finance_schema.sql\", \"w\", encoding=\"utf-8\") as sf:\n                        sf.write(code)\n                    found = True\n                    break\n            \n            # If not in tool_calls, check content\n            content = obj.get(\"content\", \"\")\n            if not found and content and \"CREATE TABLE public.fin_customers\" in content:\n                print(f\"Found SQL table definition in content at line {idx}\")\n                with open(\"finance_schema.sql\", \"w\", encoding=\"utf-8\") as sf:\n                    sf.write(content)\n                found = True\n                break\n\nif not found:\n    print(\"Could not find the SQL code in the transcript.\")\nelse:\n    print(\"Successfully extracted SQL schema to finance_schema.sql\")\n"